#include "FoliageWind.hpp"

#include <Windows.h>

#include <algorithm>
#include <cmath>
#include <cstring>

#include "Wind.hpp"
#include "rg_host.h"
// generated by plugin\shaders\build_shaders.py from the installed game's shader cache
#include "NCWFoliagePatch.hpp"

namespace
{
RED4ext::v1::PluginHandle g_handle = nullptr;
const RED4ext::v1::Sdk* g_sdk = nullptr;

NCW::FoliageWind::Settings g_settings;
NCW::FoliageWind::Stats g_stats;

// set once, in REDGraph's Load (its registration window); read from the main thread afterwards
std::atomic<const rg_host*> g_host{nullptr};
rg_handle g_patch = 0;
rg_handle g_lease = 0;
rg_handle g_cbuffer = 0;

// main thread only
bool g_missingLogged = false;
bool g_statusLogged = false;
int g_selected = -1; // the variant last selected: -1 vanilla (initial), 0 ours

// m_windImpulseVolumeUpdate_Shapes (game 2.31), the shader the patch replaces
constexpr std::uint8_t kShapesHash[16] = {0xb8, 0x8a, 0xf9, 0x3e, 0x42, 0x1f, 0x88, 0xee,
                                          0x27, 0x8f, 0x2b, 0xa0, 0x0f, 0x21, 0x4d, 0x6d};
constexpr std::uint32_t kLeaseRegister = 3; // b3: the shapes shader reads only b12
constexpr std::uint32_t kGrid = 16;         // 16 x 16 columns of 2 m (4 x 4 cells of the volume)
constexpr std::uint32_t kCb12VolumeCentre = 53 * 16; // cb12 register 53: the volume's centre, .w the
                                                     // vertex shaders' strength scale
constexpr float kPi = 3.14159265f;

struct Float4
{
    float x, y, z, w;
};
Float4 g_grid[kGrid * kGrid];

const char* ErrorName(rg_handle aCode)
{
    switch (aCode)
    {
    case RG_E_ARG: return "bad descriptor";
    case RG_E_TAKEN: return "another client holds that shader";
    case RG_E_FULL: return "a host table is full";
    case RG_E_UNSUPPORTED: return "not in this REDGraph";
    case RG_E_LATE: return "registration closed";
    case RG_E_BLOB: return "the patch blob was refused";
    default: return "error";
    }
}

// ---- the field, as NCWWind.reds computes it (keep the two in step) -------------------------------
struct V3
{
    float x, y, z;
};

V3 Dir(float aHeadingDeg)
{
    const float r = aHeadingDeg * kPi / 180.0f;
    return {std::sin(r), std::cos(r), 0.0f};
}

float GustClock(const NCW::FoliageWind::FieldState& f, float aX, float aY)
{
    const V3 d = Dir(f.heading);
    return f.clock - (aX * d.x + aY * d.y) / std::max(3.0f, f.frontSpeed);
}

float GustAt(const NCW::FoliageWind::FieldState& f, float aX, float aY)
{
    const float t = GustClock(f, aX, aY);
    const float s = f.seed;
    const float g = 0.55f * std::sin(t * 0.71f + s) + 0.35f * std::sin(t * 1.93f + s * 2.0f) +
                    0.25f * std::sin(t * 0.29f + s * 3.0f) - 0.25f;
    return std::clamp(g / 0.9f, 0.0f, 1.0f);
}

float GustHeadingAt(const NCW::FoliageWind::FieldState& f, float aX, float aY)
{
    const float t = GustClock(f, aX, aY);
    return f.heading + 15.0f * std::sin(t * 0.5f + f.seed) * GustAt(f, aX, aY);
}

// NCWWind.AtTurb(p, 10 m, 0): trees, at the 10 m reference height
V3 At(const NCW::FoliageWind::FieldState& f, float aX, float aY, float aZ)
{
    const float t = f.clock;
    const float s = f.seed;
    const float speed = f.mean * (1.0f + f.gust * 2.0f * GustAt(f, aX, aY));
    const V3 d = Dir(GustHeadingAt(f, aX, aY));
    const float a = f.mean * f.turb;
    const float ex = std::sin(aX * 0.21f + t * 1.7f + s) * std::sin(aY * 0.17f - t * 1.3f);
    const float ey = std::sin(aY * 0.23f + t * 1.1f + s) * std::cos(aX * 0.19f + t * 0.9f);
    const float ez = 0.5f * std::sin((aX + aY) * 0.15f + t * 2.1f) * std::sin(aZ * 0.3f + t + s);
    return {d.x * speed + ex * a, d.y * speed + ey * a, ez * a};
}

// ---- registration, in REDGraph's Load ------------------------------------------------------------
void OnHost(const rg_host* aHost, void*)
{
    if (aHost->struct_size < offsetof(rg_host, engine_block) + sizeof(aHost->engine_block))
    {
        g_sdk->logger->InfoF(g_handle, "foliage wind: OFF - this REDGraph's table is too small (%u B); trees follow "
                                       "the weather curves only", aHost->struct_size);
        g_stats.state.store(3);
        g_host.store(aHost);
        return;
    }

    static const rg_blob blob = {NCW::Shaders::kFoliagePatchBytes, NCW::Shaders::kFoliagePatchSize};
    rg_patch_desc d{};
    d.name = "Night City Winds: foliage wind";
    d.stage = RG_STAGE_CS;
    std::memcpy(d.hash, kShapesHash, sizeof d.hash);
    d.variants = &blob;
    d.variant_count = 1;
    d.initial_variant = -1; // the engine's shader until Update selects ours (everything granted)
    d.priority = 0;
    g_patch = aHost->patch_register(&d);

    if (g_patch > 0)
    {
        // NOT READY until the first write: the shader stays vanilla until the grid exists
        g_cbuffer = aHost->cbuffer_create(sizeof g_grid, 3, nullptr);
        if (g_cbuffer > 0)
        {
            rg_lease_desc l{};
            l.name = "Night City Winds: foliage wind grid";
            l.stage = RG_STAGE_CS;
            l.kind = RG_KIND_CBV;
            l.reg = kLeaseRegister;
            l.patches = &g_patch;
            l.patch_count = 1;
            l.cbuffer = g_cbuffer;
            g_lease = aHost->lease_register(&l);
        }
    }

    const rg_handle bad = g_patch <= 0 ? g_patch : g_cbuffer <= 0 ? g_cbuffer : g_lease <= 0 ? g_lease : 0;
    if (bad < 0)
    {
        g_sdk->logger->InfoF(g_handle, "foliage wind: OFF - REDGraph refused it (patch %d, cbuffer %d, lease %d: %s); "
                                       "trees follow the weather curves only", g_patch, g_cbuffer, g_lease,
                             ErrorName(bad));
        g_patch = 0;
        g_stats.state.store(3);
    }
    else
    {
        g_sdk->logger->InfoF(g_handle, "foliage wind: registered with REDGraph (host API %u) - the wind impulse volume "
                                       "gets the local wind", aHost->version);
        g_stats.state.store(1);
    }
    g_host.store(aHost);
}

// once the patch has run or been refused: one line with what REDGraph decided
void LogStatusOnce(const rg_host* aHost, float aStrengthScale)
{
    rg_patch_stats ps{};
    aHost->patch_stats(g_patch, &ps);
    g_stats.swaps.store(ps.swaps);
    if (g_statusLogged)
    {
        return;
    }
    rg_lease_stats ls{};
    aHost->lease_stats(g_lease, &ls);
    if (ps.state == RG_STATE_REFUSED || ls.state == RG_STATE_REFUSED)
    {
        g_statusLogged = true;
        g_stats.state.store(3);
        g_sdk->logger->InfoF(g_handle, "foliage wind: OFF - REDGraph refused the patch (state %u) or its b3 lease "
                                       "(state %u); see redgraph-*.log", ps.state, ls.state);
    }
    else if (ps.swaps > 0)
    {
        g_statusLogged = true;
        g_stats.state.store(2);
        g_sdk->logger->InfoF(g_handle, "foliage wind: running - %llu patched dispatches, %u clone(s); the vertex "
                                       "shaders' strength scale (cb12[53].w) is %.3f",
                             static_cast<unsigned long long>(ps.swaps), ps.clones, aStrengthScale);
    }
}
} // namespace

namespace NCW::FoliageWind
{
Settings& GetSettings()
{
    return g_settings;
}

Stats& GetStats()
{
    return g_stats;
}

void Init(RED4ext::v1::PluginHandle aHandle, const RED4ext::v1::Sdk* aSdk)
{
    g_handle = aHandle;
    g_sdk = aSdk;
    // RED4ext loads plugins alphabetically: REDGraph comes after us, so this usually waits in REDGraph's
    // rendezvous and runs in its Load. If REDGraph never comes, the first Update says so.
    if (rg_host_when_ready(&OnHost, nullptr) < 0)
    {
        aSdk->logger->Info(aHandle, "foliage wind: OFF - REDGraph is not installed (or older than API 1); trees "
                                    "follow the weather curves only");
        g_missingLogged = true;
    }
}

void Update(const FieldState& aField)
{
    const rg_host* host = g_host.load();
    if (!host)
    {
        if (!g_missingLogged)
        {
            g_missingLogged = true;
            g_sdk->logger->Info(g_handle, "foliage wind: OFF - REDGraph did not load (not installed, or older than "
                                          "API 1); trees follow the weather curves only");
        }
        return;
    }
    if (g_patch <= 0)
    {
        return;
    }

    const bool on = g_settings.enabled.load() && aField.mean > 0.01f;
    const int want = on ? 0 : -1;
    if (want != g_selected)
    {
        host->patch_select(g_patch, want);
        g_selected = want;
    }
    if (!on)
    {
        return;
    }

    float cb12[kCb12VolumeCentre / 4 + 4];
    std::uint32_t size = 0;
    if (host->engine_block(RG_ENGINE_CB12, cb12, sizeof cb12, &size) == 0 || size < sizeof cb12)
    {
        return; // no frame rendered yet
    }
    const float cx = cb12[kCb12VolumeCentre / 4 + 0];
    const float cy = cb12[kCb12VolumeCentre / 4 + 1];
    const float cz = cb12[kCb12VolumeCentre / 4 + 2];

    // what the weather curves show everywhere: the field at the wind origin, without eddies
    const Vec3 o = Wind::GetOrigin();
    const float speedNow = aField.mean * (1.0f + aField.gust * 2.0f * GustAt(aField, o.x, o.y));
    const V3 curveDir = Dir(GustHeadingAt(aField, o.x, o.y));
    const V3 curve = {curveDir.x * speedNow, curveDir.y * speedNow, 0.0f};

    const float gain = g_settings.gain.load();
    float largest = 0.0f;
    for (std::uint32_t j = 0; j < kGrid; ++j)
    {
        for (std::uint32_t i = 0; i < kGrid; ++i)
        {
            // column (i, j) covers cells 4i..4i+3: centre (4i + 1.5 - 32) * 0.5 + 0.25 = 2i - 15 m from the centre
            const float x = cx + 2.0f * static_cast<float>(i) - 15.0f;
            const float y = cy + 2.0f * static_cast<float>(j) - 15.0f;
            const V3 w = At(aField, x, y, cz);
            const V3 dev = {(w.x - curve.x) * gain, (w.y - curve.y) * gain, w.z * gain};
            const float len = std::sqrt(dev.x * dev.x + dev.y * dev.y + dev.z * dev.z);
            largest = std::max(largest, len);
            // .w as the engine's shapes write it: the push's length, at most 0.4 a frame
            g_grid[j * kGrid + i] = {dev.x, dev.y, dev.z, std::min(0.4f, len)};
        }
    }
    host->cbuffer_write(g_cbuffer, 0, g_grid, sizeof g_grid);
    g_stats.lastMax.store(largest);
    const auto n = g_stats.writes.fetch_add(1) + 1;
    if (n % 300 == 0)
    {
        LogStatusOnce(host, cb12[kCb12VolumeCentre / 4 + 3]);
    }
}
} // namespace NCW::FoliageWind
